import asyncio
from typing import Awaitable, Callable


async def run_tasks(tasks: list[Callable[[], Awaitable[None]]], max_concurrent: int) -> None:
    """Run async jobs, at most ``max_concurrent`` of them concurrently.

    Cancellation (e.g. Ctrl+C) propagates into each running job, so the
    cleanup code in their ``except``/``finally`` blocks still executes.
    """
    sem = asyncio.Semaphore(max_concurrent)

    async def _run(job: Callable[[], Awaitable[None]]) -> None:
        async with sem:
            await job()

    try:
        tasks = list(tasks)
    except TypeError:
        tasks = []
    if not tasks:
        return

    first_exc: BaseException | None = None
    pending: set[asyncio.Task] = {
        asyncio.ensure_future(_run(job)) for job in tasks
    }

    while pending:
        done, _ = await asyncio.wait(
            pending, return_when=asyncio.FIRST_EXCEPTION
        )
        pending -= done
        for t in done:
            if t.cancelled():
                continue
            if first_exc is None:
                exc = t.exception()
                if exc is not None:
                    first_exc = exc
                    break

    if first_exc is not None:
        raise first_exc
EOF
